/* ==========================================================================
   EvoCloud Interior Page Application Slideshow
   --------------------------------------------------------------------------
   Targets the page-app slideshow widget output (grid type):
     .evo_application_slideshow_wrapper > .evo_slideshow
       > .evo_slideshow_slides_wrapper > .evo_slideshow_slide > img

   Usage: paste as a CSS entry in the customer theme and apply it to the
   interior page template(s) where page-app slideshows render.

   All selectors are body-prefixed AND element-qualified (div.foo) so they
   out-rank both evo_common.css and earlier theme CSS entries. The widget JS
   (evo_cloud_widget.js process_evo_slideshows) re-applies inline width,
   min-width, and transform to every img twice per second, so the image
   rules that fight those use !important on purpose. Do not remove them.

   KNOWN BUG THIS FILE FIXES: a common theme rule
     .evo_application_slideshow_wrapper div.evo_slideshow_slides_wrapper
        div.evo_slideshow_slide  ( opacity: 0 )
   has specificity (0,3,2) and silently beats every
     ... .evo_slideshow_slide.current_slide ( opacity: 1 )
   rule written at (0,3,1) or lower, so NO slide is ever visible.
   The current_slide rule below is written at (0,4,3) to win.
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. Size knobs. This is the only block you should need to edit per site.
      Customer target for this site: 1000px x 400px.
      --evo-int-ss-ratio must equal width / height (1000 / 400 = 2.5).
      --evo-int-ss-fit: cover (fill + crop) or contain (letterbox, no crop).
   -------------------------------------------------------------------------- */
body .evo_application_slideshow_wrapper {
    --evo-int-ss-width: 1000px;
    --evo-int-ss-height: 400px;
    --evo-int-ss-ratio: 2.5;
    --evo-int-ss-fit: cover;
    --evo-int-ss-bg: #1a1a1a;

    width: var(--evo-int-ss-width);
    max-width: 100vw;
    height: var(--evo-int-ss-height);
    max-height: none;
    margin: 30px auto;
    padding:0;
    position: relative;
    display: block;
    overflow: hidden;
    background-color: var(--evo-int-ss-bg);
    z-index: 1;
    
}

/* The injected .evo_slideshow div and its slide strip fill the wrapper.
   The existing theme sets height: var(--slideshow-height) !important on the
   slides wrapper, so this one needs !important to win. */
body .evo_application_slideshow_wrapper div.evo_slideshow {
    height: 100%;
    position: relative;
}

body .evo_application_slideshow_wrapper div.evo_slideshow_slides_wrapper {
    height: 100% !important;
    width: 100%;
    position: relative;
    display: block !important;
}

/* --------------------------------------------------------------------------
   2. Slides: stacked, cross-fading.
   -------------------------------------------------------------------------- */
body .evo_application_slideshow_wrapper div.evo_slideshow_slides_wrapper div.evo_slideshow_slide {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    display: block;
    opacity: 0;
    transition: opacity 0.9s ease-in-out;
    overflow: hidden;
    background-color: var(--evo-int-ss-bg);
}

/* THE VISIBILITY FIX: (0,4,3) beats the stray (0,3,2) opacity:0 rule. */
body .evo_application_slideshow_wrapper div.evo_slideshow_slides_wrapper div.evo_slideshow_slide.current_slide {
    opacity: 1;
    z-index: 10;
}

/* --------------------------------------------------------------------------
   3. Images: centered, cover/contain, never distorted.
      !important is required: the widget JS re-applies inline width,
      min-width, and transform every 500ms, and the theme pins height to
      var(--slideshow-height).
   -------------------------------------------------------------------------- */
body .evo_application_slideshow_wrapper div.evo_slideshow_slides_wrapper div.evo_slideshow_slide img {
    display: block;
    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;
    height: 100% !important;
    max-height: 100% !important;
    margin: 0;
    transform: none !important;
    object-fit: var(--evo-int-ss-fit);
    object-position: center center;
}

/* Slides built from a custom URL (video/iframe embeds) get the same box. */
body .evo_application_slideshow_wrapper div.evo_slideshow_slides_wrapper div.evo_slideshow_slide video,
body .evo_application_slideshow_wrapper div.evo_slideshow_slides_wrapper div.evo_slideshow_slide iframe {
    display: block;
    width: 100% !important;
    height: 100% !important;
    border: 0;
    object-fit: var(--evo-int-ss-fit);
}

/* --------------------------------------------------------------------------
   4. Caption: polished lower-third overlay instead of the legacy
      negative-margin hack (margin-top: -120px). Sized for a 400px box.
      Set --evo-int-ss-accent to the site brand color (used for the label
      accent bar and caption buttons).
   -------------------------------------------------------------------------- */
body .evo_application_slideshow_wrapper div.evo_slideshow_slide div.evo_slideshow_caption_wrapper {
    display: none;
}

/* All overlay positioning lives on the current_slide selector at (0,4,3)
   because themes commonly restyle the caption at (0,4,2) with
   position: relative and margin-top: -120px - both must lose. */
body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide div.evo_slideshow_caption_wrapper {
    --evo-int-ss-accent: #ffc425;

    display: block;
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    top: auto;
    margin: 0;
    padding: 36px 24px 30px 24px;
    background: linear-gradient(to bottom, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.45) 40%, rgba(0, 0, 0, 0.78));
    z-index: 20;
    pointer-events: none;
    animation: evo_int_ss_caption_in 0.9s ease-out both;
}

@keyframes evo_int_ss_caption_in {
    from {
        opacity: 0;
        transform: translateY(14px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Slides with no label/text render a noshow wrapper - keep it gone. */
body .evo_application_slideshow_wrapper div.evo_slideshow_slide div.evo_slideshow_caption_wrapper_noshow {
    display: none;
}

body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide div.evo_slideshow_slide_content {
    padding: 0;
    margin: 0;
    max-width: 75%;
    margin-left: auto;
    margin-right: auto;
}

/* Label. The current_slide selector out-ranks theme label rules at (0,4,1)
   and the 15vh padding-top that evo_common.css puts on labels (meant for
   full-height home heroes, absurd inside a 400px box). The accent bar is
   drawn with a border-bottom on an inline-block so it hugs the text. */
body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide .evo_slideshow_slide_label {
    display: inline-block;
    padding: 0 2px 6px 2px;
    margin: 0 0 4px 0;
    color: #ffffff;
    font-size: 1.45rem;
    font-weight: 700;
    line-height: 1.25;
    letter-spacing: 0.04em;
    text-shadow: 0 2px 6px rgba(0, 0, 0, 0.85);
    border-bottom: 3px solid var(--evo-int-ss-accent);
}

body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide div.evo_slideshow_slide_content p {
    margin: 6px 0 0 0;
    color: rgba(255, 255, 255, 0.95);
    font-size: 1.05rem;
    line-height: 1.45;
    text-shadow: 0 1px 4px rgba(0, 0, 0, 0.85);
}

/* Caption buttons: pill buttons in the accent color. They stay clickable
   even though the caption strip itself lets clicks pass through. */
body .evo_application_slideshow_wrapper div.evo_slideshow_slide div.evo_slideshow_caption_wrapper a {
    pointer-events: auto;
}

body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide div.evo_slideshow_caption_wrapper ol {
    margin: 10px 0 0 0;
    padding: 0;
    list-style: none;
}

body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide div.evo_slideshow_caption_wrapper ol li {
    display: inline-block;
    margin: 4px 6px 0 6px;
}

body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide div.evo_slideshow_caption_wrapper a.btn {
    display: inline-block;
    padding: 7px 18px;
    background-color: var(--evo-int-ss-accent);
    color: #1a1a1a;
    font-size: 0.95rem;
    font-weight: 600;
    line-height: 1.2;
    text-decoration: none;
    text-shadow: none;
    border: 0;
    border-radius: 999px;
    transition: filter 0.15s ease-in-out, transform 0.15s ease-in-out;
}

body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide div.evo_slideshow_caption_wrapper a.btn:hover,
body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide div.evo_slideshow_caption_wrapper a.btn:focus {
    filter: brightness(1.08);
    transform: translateY(-1px);
    color: #1a1a1a;
}

/* --------------------------------------------------------------------------
   5. Controls: vertically centered pill on the right edge.
   -------------------------------------------------------------------------- */
body .evo_application_slideshow_wrapper div.evo_slideshow_controls {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    right: 10px;
    padding: 6px 5px;
    background-color: rgba(20, 20, 20, 0.55);
    border-radius: 18px;
    z-index: 30;
}

body .evo_application_slideshow_wrapper div.evo_slideshow_controls a {
    display: block;
    height: 28px;
    opacity: 0.85;
    cursor: pointer;
    text-align: center;
}

body .evo_application_slideshow_wrapper div.evo_slideshow_controls a:hover,
body .evo_application_slideshow_wrapper div.evo_slideshow_controls a:focus {
    opacity: 1;
}

body .evo_application_slideshow_wrapper div.evo_slideshow_controls a i {
    color: #ffffff;
    font-size: 18px;
    line-height: 28px;
}

/* --------------------------------------------------------------------------
   6. Indicator dots: bottom center. The existing theme hides these; delete
      this whole section if the customer prefers them hidden.
   -------------------------------------------------------------------------- */
body .evo_application_slideshow_wrapper ul.evo_slideshow_indicators {
    display: block;
    position: absolute;
    bottom: 8px;
    left: 50%;
    transform: translateX(-50%);
    margin: 0;
    padding: 0;
    list-style: none;
    z-index: 30;
    line-height: 0;
}

body .evo_application_slideshow_wrapper ul.evo_slideshow_indicators li {
    display: inline-block;
    width: 10px;
    height: 10px;
    margin: 0 4px;
    border-radius: 50%;
    background-color: rgba(255, 255, 255, 0.45);
    border: 1px solid rgba(0, 0, 0, 0.25);
}

body .evo_application_slideshow_wrapper ul.evo_slideshow_indicators li.current_slide {
    background-color: #ffffff;
}

/* --------------------------------------------------------------------------
   7. Photo credits: keep above the image, bottom-left.
   -------------------------------------------------------------------------- */
body .evo_application_slideshow_wrapper div.evo_slideshow_photo_credits_wrapper {
    position: absolute;
    left: 10px;
    bottom: 8px;
    z-index: 25;
}

/* --------------------------------------------------------------------------
   8. Responsive: below the fixed width, hold the aspect ratio instead of
      a fixed height so cover-cropping stays consistent.
   -------------------------------------------------------------------------- */
@media (max-width: 1050px) {
    body .evo_application_slideshow_wrapper {
        width: 100%;
        height: auto;
        aspect-ratio: var(--evo-int-ss-ratio);
        max-height: none;
    }
}

@media (max-width: 600px) {
    body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide .evo_slideshow_slide_label {
        font-size: 1.1rem;
    }

    body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide div.evo_slideshow_slide_content p {
        font-size: 0.95rem;
    }

    body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide div.evo_slideshow_caption_wrapper {
        padding: 20px 14px 26px 14px;
    }

    body .evo_application_slideshow_wrapper div.evo_slideshow_slide.current_slide div.evo_slideshow_slide_content {
        max-width: 92%;
    }
}

 /* Drop into the tenant theme CSS to keep styling out of the template. */
.evo_ncv2 {
  --evo-ncv2-items: 3;
  --evo-ncv2-gap: 20px;
  /* Other knobs available:
     --evo-ncv2-accent      (link/dot/focus color)
     --evo-ncv2-radius      (card corner radius)
     --evo-ncv2-bg          (card background)
     --evo-ncv2-fg          (primary text)
     --evo-ncv2-muted       (secondary text)
     --evo-ncv2-shadow      (resting card shadow -- filter: drop-shadow stack)
     --evo-ncv2-shadow-hover (hover card shadow -- filter: drop-shadow stack)
     --evo-ncv2-duration    (slide animation, default 700ms)
     --evo-ncv2-easing      (slide easing curve)
  */
}

.evo_ncv2 { --evo-ncv2-cols: var(--evo-ncv2-items, 4); }
@media (max-width:1100px){ .evo_ncv2{ --evo-ncv2-cols: min(var(--evo-ncv2-items,4), 3); } }
@media (max-width: 960px){ .evo_ncv2{ --evo-ncv2-cols: min(var(--evo-ncv2-items,4), 2); padding:0 12px; } }
@media (max-width: 520px){ .evo_ncv2{ --evo-ncv2-cols: 1; --evo-ncv2-gap:14px; } }
.evo_ncv2__slide { flex: 0 0 calc((100% - (var(--evo-ncv2-cols) - 1) * var(--evo-ncv2-gap)) / var(--evo-ncv2-cols)); }



.evo_ncv2 {
    max-width: 100vw;
    min-width: 0;          /* key: lets the widget shrink inside grid/flex parents */
    overflow: hidden;
}
.evo_ncv2__viewport {
    max-width: 100%;
    overflow-x: hidden;    /* clips the full-width track (the carousel mechanism) */
}
.evo_ncv2__track {
    min-width: 0;
} 
